<script setup>
import { ref } from 'vue';
import ApiService from '@/admin/services/ApiService';
const api=ApiService.getInstance(), code=ref(''), ticket=ref(null), error=ref(''), busy=ref(false);
async function find() { busy.value=true;error.value='';ticket.value=null;try {const r=await api.get('/api/admin/tickets',{params:{search:code.value.trim()}});ticket.value=r.data.data.data.find(t=>t.code===code.value.trim());if(!ticket.value) error.value='Entrada no encontrada.';} catch(e){error.value=e.response?.data?.message??'No se pudo buscar la entrada.';} finally{busy.value=false;} }
async function validate() {busy.value=true;try {const r=await api.post('/api/admin/tickets/'+ticket.value.id+'/mark-used');ticket.value=r.data.data;} catch(e){error.value=e.response?.data?.error?.message??e.response?.data?.message??'No se pudo validar la entrada.';} finally{busy.value=false;} }
</script>
<template><h1 class="page-title mb-4">Validar entradas</h1><form class="card card-body mb-4" @submit.prevent="find"><label for="ticket-code" class="form-label">Código de entrada</label><div class="input-group"><input id="ticket-code" v-model="code" autofocus class="form-control" required placeholder="TCK-…"><button class="btn btn-primary" :disabled="busy">Buscar</button></div></form><div v-if="error" class="alert alert-danger" role="alert">{{ error }}</div><div v-if="ticket" class="card card-body"><h2>{{ ticket.code }}</h2><p>{{ ticket.orderItem?.name ?? ticket.order_item?.name }} · {{ ticket.order?.buyer?.name }} {{ ticket.order?.buyer?.last_name }}</p><p>Función: {{ new Date(ticket.presentation?.starts_at).toLocaleString('es-AR') }}</p><p>Estado: {{ ({VALID:'Válida',USED:'Ya utilizada',CANCELED:'Cancelada'})[ticket.status] }}</p><button v-if="ticket.status==='VALID'" class="btn btn-success align-self-start" :disabled="busy" @click="validate">Confirmar ingreso</button></div></template>
